const pptxgen = require("pptxgenjs");
const fs = require("fs");
const path = require("path");

// Create presentation
let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Global CO2 Emissions: Trends, Regional Shifts, and Per Capita Inequalities";
pres.author = "Climate Analysis";

// Color palette - authoritative climate theme
const COLORS = {
  darkBg: "1A2F38",       // Deep teal-navy for title slides
  primary: "0D7377",       // Teal
  secondary: "14919B",    // Lighter teal
  accent: "E8B44F",       // Gold accent
  lightBg: "F7F9FA",      // Near-white
  text: "2C3E50",         // Dark slate
  muted: "6B7C8A",        // Muted gray-blue
  white: "FFFFFF",
  chartColors: ["0D9488", "14B8A6", "5EEAD4", "0F766E", "115E59", "134E4A"]
};

// ============================================================
// SLIDE 1: Title Slide
// ============================================================
let slide1 = pres.addSlide();
slide1.background = { color: COLORS.darkBg };

// Decorative accent shape - top right
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 7.5, y: 0, w: 2.5, h: 0.15,
  fill: { color: COLORS.accent }
});

// Title
slide1.addText("Global CO₂ Emissions", {
  x: 0.7, y: 1.6, w: 8.5, h: 1.0,
  fontSize: 44, fontFace: "Georgia", bold: true,
  color: COLORS.white, align: "left"
});

slide1.addText("Trends, Regional Shifts, and Per Capita Inequalities", {
  x: 0.7, y: 2.6, w: 8.5, h: 0.6,
  fontSize: 24, fontFace: "Calibri",
  color: COLORS.secondary, align: "left"
});

// Scope subtitle
slide1.addText("1750 – 2024", {
  x: 0.7, y: 3.4, w: 3, h: 0.5,
  fontSize: 18, fontFace: "Calibri", bold: true,
  color: COLORS.accent, align: "left"
});

// Divider line
slide1.addShape(pres.shapes.LINE, {
  x: 0.7, y: 4.1, w: 5, h: 0,
  line: { color: COLORS.secondary, width: 1 }
});

// Data source attribution
slide1.addText("Data Source: Global Carbon Budget 2025, NASA Mauna Loa Observatory", {
  x: 0.7, y: 4.4, w: 8, h: 0.4,
  fontSize: 12, fontFace: "Calibri",
  color: COLORS.muted, align: "left"
});

// Bottom decorative bar
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 5.425, w: 10, h: 0.2,
  fill: { color: COLORS.primary }
});

// ============================================================
// SLIDE 2: Atmospheric CO2 Milestone
// ============================================================
let slide2 = pres.addSlide();
slide2.background = { color: COLORS.lightBg };

// Title
slide2.addText("Atmospheric CO₂ Reaches 429 ppm", {
  x: 0.5, y: 0.4, w: 9, h: 0.6,
  fontSize: 32, fontFace: "Georgia", bold: true,
  color: COLORS.text, align: "left"
});

slide2.addText("50% Above Pre-Industrial Levels", {
  x: 0.5, y: 0.95, w: 9, h: 0.4,
  fontSize: 18, fontFace: "Calibri",
  color: COLORS.muted, align: "left"
});

// Large stat callout
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.6, w: 4, h: 2.2,
  fill: { color: COLORS.primary },
  shadow: { type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.15 }
});

slide2.addText("429", {
  x: 0.5, y: 1.75, w: 4, h: 1.2,
  fontSize: 72, fontFace: "Georgia", bold: true,
  color: COLORS.white, align: "center"
});

slide2.addText("ppm (February 2026)", {
  x: 0.5, y: 2.95, w: 4, h: 0.4,
  fontSize: 16, fontFace: "Calibri",
  color: COLORS.white, align: "center"
});

slide2.addText("Mauna Loa Observatory", {
  x: 0.5, y: 3.35, w: 4, h: 0.3,
  fontSize: 11, fontFace: "Calibri",
  color: "B8E0E3", align: "center"
});

// Context box
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 5, y: 1.6, w: 4.5, h: 2.2,
  fill: { color: COLORS.white },
  line: { color: "E0E7EA", width: 1 }
});

slide2.addText([
  { text: "Pre-industrial baseline: ~280 ppm", options: { bullet: true, breakLine: true } },
  { text: "Current level 1.5× greater than the natural increase at the end of the last ice age", options: { bullet: true, breakLine: true } },
  { text: "That natural shift took thousands of years; the current rise occurred in ~2 centuries", options: { bullet: true, breakLine: true } },
  { text: "Driven primarily by burning coal, oil, and natural gas", options: { bullet: true } }
], {
  x: 5.2, y: 1.8, w: 4.1, h: 1.9,
  fontSize: 13, fontFace: "Calibri",
  color: COLORS.text, valign: "top"
});

// Timeline note
slide2.addText("Source: NOAA Mauna Loa Observatory, NASA Climate Vital Signs", {
  x: 0.5, y: 5.2, w: 9, h: 0.3,
  fontSize: 10, fontFace: "Calibri",
  color: COLORS.muted, align: "left"
});

// ============================================================
// SLIDE 3: Global Emissions Six-Fold Since 1950
// ============================================================
let slide3 = pres.addSlide();
slide3.background = { color: COLORS.lightBg };

// Title
slide3.addText("Global Fossil Fuel CO₂ Emissions Grew Six-Fold", {
  x: 0.5, y: 0.4, w: 9, h: 0.6,
  fontSize: 30, fontFace: "Georgia", bold: true,
  color: COLORS.text, align: "left"
});

slide3.addText("6 Billion to 35+ Billion Tonnes", {
  x: 0.5, y: 0.95, w: 9, h: 0.35,
  fontSize: 16, fontFace: "Calibri",
  color: COLORS.muted, align: "left"
});

// Bar chart showing trajectory
const chartData = [{
  name: "Emissions (Bt)",
  labels: ["1950", "1970", "1990", "2000", "2010", "2024"],
  values: [6, 12, 22, 25, 32, 37]
}];

slide3.addChart(pres.charts.BAR, chartData, {
  x: 0.5, y: 1.4, w: 5.5, h: 3.2,
  barDir: "col",
  chartColors: [COLORS.primary],
  chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
  catAxisLabelColor: COLORS.muted,
  valAxisLabelColor: COLORS.muted,
  valGridLine: { color: "E8ECEF", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.text,
  showLegend: false,
  catAxisTitle: "Year",
  valAxisTitle: "Billion Tonnes"
});

// Key milestones callout on right
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 1.4, w: 3.2, h: 3.2,
  fill: { color: COLORS.white },
  line: { color: "E0E7EA", width: 1 }
});

slide3.addText("Key Inflection Points", {
  x: 6.5, y: 1.55, w: 2.8, h: 0.35,
  fontSize: 14, fontFace: "Calibri", bold: true,
  color: COLORS.text
});

slide3.addText([
  { text: "6 Bt", options: { bold: true } },
  { text: " — World emissions in 1950", options: { breakLine: true } },
  { text: " ", options: { breakLine: true } },
  { text: "20 Bt", options: { bold: true } },
  { text: " — Crossed by 1990", options: { breakLine: true } },
  { text: " ", options: { breakLine: true } },
  { text: "35+ Bt", options: { bold: true } },
  { text: " — Current annual emissions", options: { breakLine: true } },
  { text: " ", options: { breakLine: true } },
  { text: "Growth has slowed but not yet peaked", options: { italic: true } }
], {
  x: 6.5, y: 2.0, w: 2.8, h: 2.4,
  fontSize: 12, fontFace: "Calibri",
  color: COLORS.text
});

// Footer
slide3.addText("Source: Global Carbon Budget 2025 | Reference: figure_2.jpg", {
  x: 0.5, y: 5.2, w: 9, h: 0.3,
  fontSize: 10, fontFace: "Calibri",
  color: COLORS.muted, align: "left"
});

// ============================================================
// SLIDE 4: China Surpasses US Total Emissions
// ============================================================
let slide4 = pres.addSlide();
slide4.background = { color: COLORS.lightBg };

// Title
slide4.addText("China Now Emits Over 12 Billion Tonnes", {
  x: 0.5, y: 0.4, w: 9, h: 0.6,
  fontSize: 30, fontFace: "Georgia", bold: true,
  color: COLORS.text, align: "left"
});

slide4.addText("More Than Double the United States", {
  x: 0.5, y: 0.95, w: 9, h: 0.35,
  fontSize: 16, fontFace: "Calibri",
  color: COLORS.muted, align: "left"
});

// Horizontal bar chart for country emissions
const countryData = [{
  name: "Annual CO₂ (Bt)",
  labels: ["China", "United States", "India", "EU-27", "Germany", "United Kingdom", "Brazil", "France"],
  values: [12.5, 5.0, 3.0, 2.7, 0.6, 0.3, 0.5, 0.3]
}];

slide4.addChart(pres.charts.BAR, countryData, {
  x: 0.5, y: 1.4, w: 5.5, h: 3.4,
  barDir: "bar",
  chartColors: [COLORS.primary, COLORS.secondary, "5EEAD4", "0F766E", "115E59", "134E4A", "0D9488", "14B8A6"],
  chartArea: { fill: { color: COLORS.white }, roundedCorners: true },
  catAxisLabelColor: COLORS.text,
  valAxisLabelColor: COLORS.muted,
  valGridLine: { color: "E8ECEF", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.text,
  showLegend: false,
  valAxisTitle: "Billion Tonnes per Year"
});

// Key insights box
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 6.3, y: 1.4, w: 3.2, h: 3.4,
  fill: { color: COLORS.primary }
});

slide4.addText("Key Insights", {
  x: 6.5, y: 1.55, w: 2.8, h: 0.35,
  fontSize: 14, fontFace: "Calibri", bold: true,
  color: COLORS.white
});

slide4.addText([
  { text: "China: ~27% of global total", options: { breakLine: true } },
  { text: " ", options: { breakLine: true } },
  { text: "US peaked near 6 Bt around 2005; now ~5 Bt", options: { breakLine: true } },
  { text: " ", options: { breakLine: true } },
